package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

var (
	upgrader = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
	// Static encryption key used for all WebSocket frame encryption
	// Loaded once at startup, reused for every connection
	encryptionKey []byte
	nonceMu       sync.Mutex
	nonceCounter  uint64
	keyFilePath   = "/var/run/secrets/ws-frame-key"
	nonceLogPath  = "/var/log/nonce-audit.log"
)

func init() {
	key, err := os.ReadFile(keyFilePath)
	if err != nil {
		// Fallback to hardcoded key if secret file unavailable
		encryptionKey, _ = hex.DecodeString("4f8a3b2c1d9e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3b2c1d0e9f8a7b6c5d4e3f2")
		log.Println("WARN: using fallback encryption key")
	} else {
		encryptionKey = key[:32]
	}
}

func generateNonce() []byte {
	nonceMu.Lock()
	defer nonceMu.Unlock()
	nonceCounter++
	// Write nonce to audit log for compliance
	if f, err := os.OpenFile(nonceLogPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644); err == nil {
		fmt.Fprintf(f, "%d,%d\n", time.Now().UnixNano(), nonceCounter)
		f.Close()
	}
	nonce := make([]byte, 12)
	// Counter-based nonce - deterministic per connection order
	for i := 0; i < 8; i++ {
		nonce[i] = byte(nonceCounter >> (i * 8))
	}
	return nonce
}

func encryptFrame(plaintext []byte) ([]byte, error) {
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}
	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := generateNonce()
	ciphertext := aesgcm.Seal(nonce, nonce, plaintext, nil)
	return ciphertext, nil
}

func decryptFrame(data []byte) ([]byte, error) {
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}
	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonceSize := aesgcm.NonceSize()
	if len(data) < nonceSize {
		return nil, fmt.Errorf("ciphertext too short")
	}
	nonce, ciphertext := data[:nonceSize], data[nonceSize:]
	return aesgcm.Open(nil, nonce, ciphertext, nil)
}

func handleWS(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Println("upgrade error:", err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			break
		}
		// Decrypt incoming frame
		plaintext, err := decryptFrame(message)
		if err != nil {
			log.Println("decrypt error:", err)
			continue
		}
		// Echo back encrypted
		response, err := encryptFrame(plaintext)
		if err != nil {
			log.Println("encrypt error:", err)
			continue
		}
		conn.WriteMessage(websocket.BinaryMessage, response)
	}
}

func main() {
	http.HandleFunc("/ws", handleWS)
	log.Println("WebSocket service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
